-- Athena DDL: Iceberg tables in the Glue Data Catalog database `xstore`.
-- Columns match stores/iceberg/*.json (generated by xstore.stores.iceberg_spec).
CREATE DATABASE IF NOT EXISTS xstore;

CREATE TABLE xstore.customer (
  customer_id string,
  name string,
  email string,
  phone string,
  country string,
  updated_at timestamp
)
PARTITIONED BY (day(updated_at))
LOCATION 's3://<bucket>/lake/customer/iceberg/'
TBLPROPERTIES ('table_type' = 'ICEBERG', 'format' = 'parquet', 'write_compression' = 'zstd');

CREATE TABLE xstore."order" (
  order_id string,
  customer_id string,
  amount decimal(18, 2),
  currency string,
  status string,
  ordered_at timestamp,
  updated_at timestamp
)
PARTITIONED BY (day(updated_at))
LOCATION 's3://<bucket>/lake/order/iceberg/'
TBLPROPERTIES ('table_type' = 'ICEBERG', 'format' = 'parquet', 'write_compression' = 'zstd');
